// Upipination maintenance Worker
// Runs on Cloudflare in front of upipination.com. Everything goes straight to the site as usual;
// only when the PC doesn't answer (turned off, tunnel down, restarting) it shows a maintenance page
// instead of Cloudflare's error. Deploy: see maintenance/README.md
const DOWN = new Set([502, 503, 504, 520, 521, 522, 523, 524, 525, 526, 527, 530]);

export default {
  async fetch(req) {
    let res;
    try {
      res = await fetch(req);
    } catch (e) {
      return maintenance(req);
    }
    return DOWN.has(res.status) ? maintenance(req) : res;
  }
};

function maintenance(req) {
  const path = new URL(req.url).pathname;
  const headers = { 'Cache-Control': 'no-store', 'Retry-After': '60', 'X-Robots-Tag': 'noindex, nofollow' };
  // the app's own requests get a short answer it understands; people get the page
  if (path.startsWith('/api/') || path.startsWith('/socket.io/') || req.headers.get('Upgrade')) {
    return new Response(JSON.stringify({ error: 'maintenance' }), { status: 503, headers: { ...headers, 'Content-Type': 'application/json' } });
  }
  return new Response(PAGE, { status: 503, headers: { ...headers, 'Content-Type': 'text/html; charset=utf-8' } });
}

const PAGE = `<!doctype html>
<html lang="es"><head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="robots" content="noindex, nofollow">
<title>Upipination · En mantenimiento</title>
<style>
  :root { --page:#e4d8bd; --panel:#f8f2e4; --row:#f1e8d5; --border:#9c8462; --bar1:#86603a; --bar2:#5a3c1f; --bartext:#fdf6e6; --text:#2b2418; --muted:#6e604a; --accent:#b8561b; --ticker:#fff3c4; --tickertext:#6b3d10; }
  @media (prefers-color-scheme: dark) { :root { --page:#141821; --panel:#1e2430; --row:#232a38; --border:#3e4a63; --bar1:#3d5280; --bar2:#1f2b44; --bartext:#e6ecf7; --text:#d6dbe5; --muted:#8a93a6; --accent:#ffb04a; --ticker:#2a2615; --tickertext:#ffd27a; } }
  * { box-sizing: border-box; }
  body { margin: 0; min-height: 100vh; display: grid; place-items: center; padding: 16px; background: var(--page); color: var(--text); font: 13px Verdana, Tahoma, sans-serif;
    background-image: repeating-linear-gradient(45deg, rgba(0,0,0,.035) 0 2px, transparent 2px 7px); }
  .card { width: min(420px, 100%); border: 1px solid var(--border); background: var(--panel); box-shadow: 3px 3px 0 rgba(0,0,0,.15); }
  .bar { padding: 6px 10px; background: linear-gradient(var(--bar1), var(--bar2)); color: var(--bartext); font-weight: bold; font-size: 12px; text-shadow: 1px 1px 0 rgba(0,0,0,.3); }
  .body { display: flex; flex-direction: column; align-items: center; gap: 10px; padding: 18px 16px 20px; text-align: center; }
  .plate { padding: 4px 18px; background: var(--ticker); color: var(--tickertext); border: 1px solid var(--border); box-shadow: 2px 2px 0 rgba(0,0,0,.2); transform: rotate(-2deg); font: italic bold 30px/1.1 'Trebuchet MS', Verdana, sans-serif; }
  img { width: 140px; height: auto; }
  .muted { color: var(--muted); font-size: 12px; }
  .retry { color: var(--accent); font-size: 12px; animation: blink 1.6s ease-in-out infinite; }
  @keyframes blink { 50% { opacity: .35; } }
  @media (prefers-reduced-motion: reduce) { .retry { animation: none; } }
</style></head>
<body>
  <main class="card">
    <div class="bar">Upipination</div>
    <div class="body">
      <div class="plate">Upipination</div>
      <img src="data:image/gif;base64," alt="Pirata bailando con una radio">
      <b>🔧 Estamos en mantenimiento</b>
      <span>El servidor está apagado o reiniciándose. Volvé en un rato.</span>
      <span class="muted">Dejá esta página abierta: se recarga sola apenas vuelva.</span>
      <span class="retry">Reintentando…</span>
    </div>
  </main>
  <script>
    // check every 20 seconds whether the site is back
    setInterval(async () => {
      try { const r = await fetch('/api/status', { cache: 'no-store' }); if (r.ok) location.reload(); } catch (e) {}
    }, 20000);
  </script>
</body></html>
`;
